        "why_flagged": "\u0648\u062C\u0648\u062F \u0634\u0631\u0637 \u0632\u0645\u0646\u064A (60 \u064A\u0648\u0645\u064B\u0627) \u0642\u062F \u064A\u0641\u0648\u062A \u0627\u0644\u0645\u0633\u062A\u0623\u062C\u0631 \u0625\u0630\u0627 \u0644\u0645 \u064A\u062A\u0627\u0628\u0639\u0647.",
        "legal_reference": "\u0627\u0644\u0645\u0627\u062F\u0629 563 \u0645\u0646 \u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0627\u0644\u0645\u062F\u0646\u064A \u0627\u0644\u0645\u0635\u0631\u064A: \u0625\u0630\u0627 \u0644\u0645 \u064A\u064F\u062D\u062F\u062F \u0645\u064A\u0642\u0627\u062A \u0645\u0639\u064A\u0646 \u0644\u0627\u0646\u062A\u0647\u0627\u0621 \u0627\u0644\u0625\u064A\u062C\u0627\u0631\u060C \u0623\u0648 \u0644\u0645 \u062A\u064F\u062D\u062F\u062F \u0645\u062F\u062A\u0647 \u0639\u0644\u0649 \u0648\u062C\u0647 \u0627\u0644\u064A\u0642\u064A\u0646\u060C \u064A\u0646\u062A\u0647\u064A \u0627\u0644\u0639\u0642\u062F \u0628\u062A\u0646\u0628\u064A\u0647 \u0623\u062D\u062F \u0627\u0644\u0645\u062A\u0639\u0627\u0642\u062F\u064A\u0646 \u0644\u0644\u0622\u062E\u0631 \u0628\u0627\u0644\u0625\u062E\u0644\u0627\u0621 \u0641\u064A \u0627\u0644\u0645\u0648\u0627\u0639\u064A\u062F \u0627\u0644\u0645\u0642\u0631\u0631\u0629 \u0642\u0627\u0646\u0648\u0646\u064B\u0627 \u0648\u0639\u0631\u0641\u064B\u0627.",
