        "clause_pattern": "\u0641\u064A \u062D\u0627\u0644\u0629 \u0627\u0644\u062A\u0623\u062E\u0631 \u0639\u0646 \u0633\u062F\u0627\u062F \u0627\u0644\u0625\u064A\u062C\u0627\u0631 \u064A\u064F\u0641\u0631\u0636 \u063A\u0631\u0627\u0645\u0629 \u0642\u062F\u0631\u0647\u0627 5% \u0639\u0646 \u0643\u0644 \u064A\u0648\u0645 \u062A\u0623\u062E\u064A\u0631",
        "risk_level": "attention",
        "risk_color": "red",
        "explanation": "\u0646\u0633\u0628\u0629 \u0627\u0644\u063A\u0631\u0627\u0645\u0629 \u0627\u0644\u064A\u0648\u0645\u064A\u0629 \u0645\u0631\u062A\u0641\u0639\u0629 \u0646\u0633\u0628\u064A\u064B\u0627 \u0648\u0642\u062F \u062A\u062A\u0631\u0627\u0643\u0645 \u0628\u0633\u0631\u0639\u0629. \u0647\u0630\u0627 \u0627\u0644\u0628\u0646\u062F \u064A\u0633\u062A\u062D\u0642 \u0645\u0631\u0627\u062C\u0639\u0629 \u062F\u0642\u064A\u0642\u0629 \u0648\u0645\u062D\u0627\u0648\u0644\u0629 \u0627\u0644\u062A\u0641\u0627\u0648\u0636 \u0639\u0644\u064A\u0647 \u0642\u0628\u0644 \u0627\u0644\u062A\u0648\u0642\u064A\u0639.",
        "why_flagged": "\u063A\u0631\u0627\u0645\u0629 \u062A\u0631\u0627\u0643\u0645\u064A\u0629 \u064A\u0648\u0645\u064A\u0629 \u0642\u062F \u062A\u0635\u0644 \u0644\u0645\u0628\u0627\u0644\u063A \u0643\u0628\u064A\u0631\u0629 \u062E\u0644\u0627\u0644 \u0623\u0633\u0627\u0628\u064A\u0639 \u0642\u0644\u064A\u0644\u0629.",
