        "legal_reference": "\u0627\u0644\u0645\u0627\u062F\u0629 570 \u0645\u0646 \u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0627\u0644\u0645\u062F\u0646\u064A \u0627\u0644\u0645\u0635\u0631\u064A: \u064A\u0644\u062A\u0632\u0645 \u0627\u0644\u0645\u0624\u062C\u0631 \u0628\u0625\u062C\u0631\u0627\u0621 \u0627\u0644\u062A\u0631\u0645\u064A\u0645\u0627\u062A \u0627\u0644\u0636\u0631\u0648\u0631\u064A\u0629 \u0644\u0644\u062D\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0644\u0639\u064A\u0646 \u0627\u0644\u0645\u0624\u062C\u0631\u0629 \u0641\u064A \u062D\u0627\u0644\u0629 \u0635\u0627\u0644\u062D\u0629 \u0644\u0644\u0627\u0646\u062A\u0641\u0627\u0639 \u0628\u0647\u0627. \u0627\u0644\u0645\u0627\u062F\u0629 580: \u064A\u0644\u062A\u0632\u0645 \u0627\u0644\u0645\u0633\u062A\u0623\u062C\u0631 \u0628\u0627\u0644\u062A\u0631\u0645\u064A\u0645\u0627\u062A \u0627\u0644\u062A\u0623\u062C\u064A\u0631\u064A\u0629 \u0627\u0644\u0628\u0633\u064A\u0637\u0629 \u0627\u0644\u0645\u0639\u062A\u0627\u062F\u0629 \u0641\u0642\u0637 (\u0643\u0625\u0635\u0644\u0627\u062D \u0627\u0644\u0632\u062C\u0627\u062C \u0648\u0627\u0644\u0645\u0641\u0627\u062A\u064A\u062D \u0627\u0644\u0628\u0633\u064A\u0637\u0629)\u060C \u0648\u0644\u064A\u0633 \u0627\u0644\u0635\u064A\u0627\u0646\u0629 \u0627\u0644\u062C\u0648\u0647\u0631\u064A\u0629.",
