        "category": "\u0645\u062F\u0629 \u0627\u0644\u0645\u0637\u0627\u0644\u0628\u0629 \u0628\u0627\u0644\u0639\u064A\u0648\u0628",
        "clause_pattern": "\u0644\u0627 \u064A\u062D\u0642 \u0644\u0644\u0645\u0634\u062A\u0631\u064A \u0627\u0644\u0645\u0637\u0627\u0644\u0628\u0629 \u0628\u0623\u064A \u0639\u064A\u0628 \u064A\u0638\u0647\u0631 \u0628\u0639\u062F \u0627\u0644\u062A\u0633\u0644\u064A\u0645",
        "risk_level": "attention",
        "risk_color": "red",
        "explanation": "\u0647\u0630\u0627 \u0627\u0644\u0634\u0631\u0637 \u0623\u0648\u0633\u0639 \u0645\u0646 \u0627\u0644\u0625\u0637\u0627\u0631 \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064A \u0627\u0644\u0645\u0639\u062A\u0627\u062F\u060C \u062D\u064A\u062B \u064A\u0645\u0646\u062D \u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0627\u0644\u0645\u0634\u062A\u0631\u064A \u0645\u0647\u0644\u0629 \u0632\u0645\u0646\u064A\u0629 \u0644\u0644\u0645\u0637\u0627\u0644\u0628\u0629 \u0628\u0627\u0644\u0639\u064A\u0648\u0628 \u0627\u0644\u062E\u0641\u064A\u0629 \u0627\u0644\u062A\u064A \u0644\u0645 \u062A\u0643\u0646 \u0638\u0627\u0647\u0631\u0629 \u0648\u0642\u062A \u0627\u0644\u0641\u062D\u0635 \u0627\u0644\u0645\u0639\u062A\u0627\u062F.",
        "why_flagged": "\u062D\u0631\u0645\u0627\u0646 \u0643\u0627\u0645\u0644 \u0645\u0646 \u062D\u0642 \u0642\u0627\u0646\u0648\u0646\u064A \u0645\u0642\u0631\u0631 \u0623\u0635\u0644\u0627\u064B \u0644\u0644\u0645\u0634\u062A\u0631\u064A \u062F\u0648\u0646 \u062D\u062F\u0648\u062F \u0632\u0645\u0646\u064A\u0629 \u0648\u0627\u0636\u062D\u0629.",
        "legal_reference": "\u0627\u0644\u0645\u0627\u062F\u0629 447 \u0645\u0646 \u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0627\u0644\u0645\u062F\u0646\u064A \u0627\u0644\u0645\u0635\u0631\u064A: \u062A\u0633\u0642\u0637 \u062F\u0639\u0648\u0649 \u0636\u0645\u0627\u0646 \u0627\u0644\u0639\u064A\u0628 \u0627\u0644\u062E\u0641\u064A \u0628\u0645\u0631\u0648\u0631 \u0633\u0646\u0629 \u0645\u0646 \u0648\u0642\u062A \u0627\u0644\u062A\u0633\u0644\u064A\u0645\u060C \u0648\u0644\u0648 \u0644\u0645 \u064A\u0643\u062A\u0634\u0641 \u0627\u0644\u0645\u0634\u062A\u0631\u064A \u0627\u0644\u0639\u064A\u0628 \u0625\u0644\u0627 \u0628\u0639\u062F \u0630\u0644\u0643. \u0643\u0645\u0627 \u062A\u0641\u0631\u0636 \u0627\u0644\u0645\u0627\u062F\u0629 22 \u0645\u0646 \u0642\u0627\u0646\u0648\u0646 \u062D\u0645\u0627\u064A\u0629 \u0627\u0644\u0645\u0633\u062A\u0647\u0644\u0643 \u0631\u0642\u0645 181 \u0644\u0633\u0646\u0629 2018 \u0636\u0645\u0627\u0646\u064B\u0627 \u0642\u0627\u0646\u0648\u0646\u064A\u064B\u0627 \u0625\u0644\u0632\u0627\u0645\u064A\u064B\u0627 \u0644\u0645\u062F\u0629 \u0633\u0646\u062A\u064A\u0646 \u0639\u0644\u0649 \u0627\u0644\u0633\u0644\u0639 \u0627\u0644\u0645\u0633\u062A\u0648\u0631\u062F\u0629 \u0623\u0648 \u0645\u062D\u0644\u064A\u0629 \u0627\u0644\u0635\u0646\u0639 (\u0648\u062A\u062F\u062E\u0644 \u0627\u0644\u0633\u064A\u0627\u0631\u0627\u062A \u0627\u0644\u062C\u062F\u064A\u062F\u0629 \u0636\u0645\u0646\u0647\u0627)\u060C \u0628\u0635\u0631\u0641 \u0627\u0644\u0646\u0638\u0631 \u0639\u0646 \u0648\u062C\u0648\u062F \u0634\u0647\u0627\u062F\u0629 \u0636\u0645\u0627\u0646 \u0645\u0646 \u0639\u062F\u0645\u0647.",
        "source": "\u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0627\u0644\u0645\u062F\u0646\u064A \u0627\u0644\u0645\u0635\u0631\u064A \u0631\u0642\u0645 131 \u0644\u0633\u0646\u0629 1948 / \u0642\u0627\u0646\u0648\u0646 \u062D\u0645\u0627\u064A\u0629 \u0627\u0644\u0645\u0633\u062A\u0647\u0644\u0643 \u0631\u0642\u0645 181 \u0644\u0633\u0646\u0629 2018"
