        "clause_pattern": "\u064A\u062A\u0645 \u0627\u0644\u0628\u064A\u0639 \u0628\u0645\u0648\u062C\u0628 \u062A\u0648\u0643\u064A\u0644 \u0639\u0627\u0645 \u062F\u0648\u0646 \u062A\u0633\u062C\u064A\u0644 \u0639\u0642\u062F \u0628\u064A\u0639 \u0631\u0633\u0645\u064A \u0641\u064A \u0627\u0644\u0634\u0647\u0631 \u0627\u0644\u0639\u0642\u0627\u0631\u064A",
        "risk_level": "attention",
