        "explanation": "\u0627\u0644\u0628\u064A\u0639 \u0628\u0627\u0644\u062A\u0648\u0643\u064A\u0644 \u0634\u0627\u0626\u0639 \u0641\u064A \u0645\u0635\u0631 \u0644\u0643\u0646\u0647 \u0644\u0627 \u064A\u064F\u0639\u062A\u0628\u0631 \u0646\u0642\u0644\u064B\u0627 \u0643\u0627\u0645\u0644\u0627\u064B \u0648\u0645\u0648\u062B\u0642\u064B\u0627 \u0644\u0644\u0645\u0644\u0643\u064A\u0629. \u0627\u0644\u0645\u0627\u0644\u0643 \u0627\u0644\u0623\u0635\u0644\u064A \u064A\u0638\u0644 \u0645\u0633\u062C\u0644\u0627\u064B \u0631\u0633\u0645\u064A\u064B\u0627\u060C \u0645\u0645\u0627 \u0642\u062F \u064A\u0639\u0631\u0651\u0636 \u0627\u0644\u0645\u0634\u062A\u0631\u064A \u0644\u0645\u0634\u0627\u0643\u0644 \u0644\u0627\u062D\u0642\u0629 (\u0643\u0648\u0641\u0627\u0629 \u0627\u0644\u0645\u0648\u0643\u0644 \u0623\u0648 \u0625\u0644\u063A\u0627\u0621 \u0627\u0644\u062A\u0648\u0643\u064A\u0644).",
        "why_flagged": "\u0627\u0644\u062A\u0648\u0643\u064A\u0644 \u0644\u0627 \u064A\u0639\u0627\u062F\u0644 \u0639\u0642\u062F \u0627\u0644\u0628\u064A\u0639 \u0627\u0644\u0645\u0633\u062C\u0644 \u0645\u0646 \u062D\u064A\u062B \u0642\u0648\u0629 \u0627\u0644\u0625\u062B\u0628\u0627\u062A \u0648\u062B\u0628\u0627\u062A \u0627\u0644\u0645\u0644\u0643\u064A\u0629 \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064A\u0629.",
        "legal_reference": "\u0639\u0642\u062F \u0627\u0644\u0628\u064A\u0639 \u0627\u0644\u0645\u0633\u062C\u0644 \u0641\u064A \u0627\u0644\u0634\u0647\u0631 \u0627\u0644\u0639\u0642\u0627\u0631\u064A \u0644\u0627 \u062A\u0648\u062C\u062F \u0644\u0647 \u0641\u062A\u0631\u0629 \u0635\u0644\u0627\u062D\u064A\u0629 \u0645\u062D\u062F\u062F\u0629\u060C \u0628\u062E\u0644\u0627\u0641 \u0628\u0639\u0636 \u0627\u0644\u0634\u0627\u0626\u0639 \u0645\u0646 \u0623\u0646 \u062A\u0648\u0642\u064A\u0639 \u0627\u0644\u0645\u0634\u062A\u0631\u064A \u0623\u0645\u0627\u0645 \u0645\u0648\u0638\u0641 \u0627\u0644\u0634\u0647\u0631 \u0627\u0644\u0639\u0642\u0627\u0631\u064A \u064A\u0643\u0648\u0646 \u0633\u0627\u0631\u064A \u0644\u0645\u062F\u0629 \u0633\u0646\u0629 \u0641\u0642\u0637. \u064A\u064F\u0646\u0635\u062D \u062F\u0627\u0626\u0645\u064B\u0627 \u0628\u0639\u0642\u062F \u0628\u064A\u0639 \u0645\u0633\u062C\u0644 \u0631\u0633\u0645\u064A\u064B\u0627 \u0628\u062F\u0644 \u0627\u0644\u0627\u0639\u062A\u0645\u0627\u062F \u0639\u0644\u0649 \u0627\u0644\u062A\u0648\u0643\u064A\u0644 \u0641\u0642\u0637.",
        "source": "\u0625\u062C\u0631\u0627\u0621\u0627\u062A \u0646\u0642\u0644 \u0627\u0644\u0645\u0644\u0643\u064A\u0629 - \u0627\u0644\u0634\u0647\u0631 \u0627\u0644\u0639\u0642\u0627\u0631\u064A \u0648\u0625\u062F\u0627\u0631\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0627\u0644\u0645\u0635\u0631\u064A\u0629"
