        "risk_level": "attention",
        "risk_color": "red",
        "explanation": "\u0627\u0644\u062C\u0645\u0639 \u0628\u064A\u0646 \u063A\u0631\u0627\u0645\u0629 \u064A\u0648\u0645\u064A\u0629 \u0645\u0631\u062A\u0641\u0639\u0629 \u062C\u062F\u064B\u0627 \u0648\u062D\u0642 \u0627\u0633\u062A\u0631\u062F\u0627\u062F \u0641\u0648\u0631\u064A \u0644\u0644\u0633\u064A\u0627\u0631\u0629 \u0642\u062F \u064A\u0645\u062B\u0644 \u0639\u0628\u0626\u064B\u0627 \u0645\u0636\u0627\u0639\u0641\u064B\u0627 \u0639\u0644\u0649 \u0627\u0644\u0645\u0634\u062A\u0631\u064A \u0648\u064A\u0633\u062A\u062D\u0642 \u062A\u0641\u0627\u0648\u0636\u064B\u0627 \u0623\u0648 \u0627\u0633\u062A\u0634\u0627\u0631\u0629 \u0642\u0627\u0646\u0648\u0646\u064A\u0629 \u0642\u0628\u0644 \u0627\u0644\u062A\u0648\u0642\u064A\u0639.",
        "why_flagged": "\u063A\u0631\u0627\u0645\u0629 \u064A\u0648\u0645\u064A\u0629 \u0645\u0631\u062A\u0641\u0639\u0629 \u062C\u062F\u064B\u0627 (10%) \u0642\u062F \u062A\u064F\u0639\u062A\u0628\u0631 \u0645\u0628\u0627\u0644\u063A\u064B\u0627 \u0641\u064A\u0647\u0627 \u0628\u0634\u0643\u0644 \u0643\u0628\u064A\u0631 \u0623\u0645\u0627\u0645 \u0627\u0644\u0642\u0636\u0627\u0621.",
        "legal_reference": "\u0627\u0644\u0645\u0627\u062F\u0629 224 \u0645\u0646 \u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0627\u0644\u0645\u062F\u0646\u064A \u0627\u0644\u0645\u0635\u0631\u064A \u062A\u064F\u062C\u064A\u0632 \u0644\u0644\u0642\u0627\u0636\u064A \u062A\u062E\u0641\u064A\u0636 \u0627\u0644\u0634\u0631\u0637 \u0627\u0644\u062C\u0632\u0627\u0626\u064A \u0625\u0630\u0627 \u0643\u0627\u0646 \u0645\u0628\u0627\u0644\u063A\u064B\u0627 \u0641\u064A\u0647 \u0625\u0644\u0649 \u062F\u0631\u062C\u0629 \u0643\u0628\u064A\u0631\u0629 \u0645\u0642\u0627\u0631\u0646\u0629 \u0628\u0627\u0644\u0636\u0631\u0631 \u0627\u0644\u0641\u0639\u0644\u064A \u0627\u0644\u0648\u0627\u0642\u0639 \u0639\u0644\u0649 \u0627\u0644\u062F\u0627\u0626\u0646.",
