        "explanation": "\u064A\u062C\u0648\u0632 \u0644\u0644\u0645\u062A\u0639\u0627\u0642\u062F\u064A\u0646 \u062A\u062D\u062F\u064A\u062F \u0642\u064A\u0645\u0629 \u0627\u0644\u062A\u0639\u0648\u064A\u0636 \u0645\u0642\u062F\u0645\u064B\u0627 \u0641\u064A \u0627\u0644\u0639\u0642\u062F \u0646\u0641\u0633\u0647\u060C \u0644\u0643\u0646 \u0647\u0630\u0627 \u0627\u0644\u0634\u0631\u0637 \u0644\u064A\u0633 \u0645\u0637\u0644\u0642\u064B\u0627 \u0648\u0642\u0627\u0628\u0644 \u0644\u0631\u0642\u0627\u0628\u0629 \u0627\u0644\u0642\u0636\u0627\u0621.",
