        "legal_reference": "\u0627\u0644\u0645\u0627\u062F\u0629 224 \u0645\u0646 \u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0627\u0644\u0645\u062F\u0646\u064A \u0627\u0644\u0645\u0635\u0631\u064A: \u064A\u062C\u0648\u0632 \u0644\u0644\u0642\u0627\u0636\u064A \u0623\u0646 \u064A\u062E\u0641\u0636 \u0627\u0644\u062A\u0639\u0648\u064A\u0636 \u0627\u0644\u0627\u062A\u0641\u0627\u0642\u064A \u0625\u0630\u0627 \u0623\u062B\u0628\u062A \u0627\u0644\u0645\u062F\u064A\u0646 \u0623\u0646 \u0627\u0644\u062A\u0642\u062F\u064A\u0631 \u0645\u0628\u0627\u0644\u063A \u0641\u064A\u0647 \u0625\u0644\u0649 \u062F\u0631\u062C\u0629 \u0643\u0628\u064A\u0631\u0629 \u0623\u0648 \u0623\u0646 \u0627\u0644\u0627\u0644\u062A\u0632\u0627\u0645 \u0627\u0644\u0623\u0635\u0644\u064A \u0646\u064F\u0641\u0630 \u0641\u064A \u062C\u0632\u0621 \u0645\u0646\u0647\u060C \u0648\u064A\u0642\u0639 \u0628\u0627\u0637\u0644\u064B\u0627 \u0623\u064A \u0627\u062A\u0641\u0627\u0642 \u064A\u0645\u0646\u0639 \u0631\u0642\u0627\u0628\u0629 \u0627\u0644\u0642\u0636\u0627\u0621 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u0634\u0631\u0637.",
