        "explanation": "\u064A\u062E\u062A\u0644\u0641 \u0627\u0644\u0639\u0642\u062F \u0627\u0644\u0628\u0627\u0637\u0644 \u0628\u0637\u0644\u0627\u0646\u064B\u0627 \u0645\u0637\u0644\u0642\u064B\u0627 (\u0643\u0623\u0646 \u064A\u0641\u062A\u0642\u062F \u0631\u0643\u0646\u064B\u0627 \u0623\u0633\u0627\u0633\u064A\u064B\u0627 \u0643\u0627\u0644\u0645\u062D\u0644 \u0623\u0648 \u0627\u0644\u0633\u0628\u0628 \u0627\u0644\u0645\u0634\u0631\u0648\u0639) \u0639\u0646 \u0627\u0644\u0639\u0642\u062F \u0627\u0644\u0642\u0627\u0628\u0644 \u0644\u0644\u0625\u0628\u0637\u0627\u0644 (\u0643\u0648\u062C\u0648\u062F \u0639\u064A\u0628 \u0641\u064A \u0627\u0644\u0631\u0636\u0627)\u060C \u062D\u064A\u062B \u064A\u0645\u0643\u0646 \u0644\u0644\u0637\u0631\u0641 \u0627\u0644\u0645\u062A\u0636\u0631\u0631 \u0648\u062D\u062F\u0647 \u0637\u0644\u0628 \u0625\u0628\u0637\u0627\u0644 \u0627\u0644\u062B\u0627\u0646\u064A \u062E\u0644\u0627\u0644 \u0645\u062F\u0629 \u0645\u0639\u064A\u0646\u0629.",
        "risk_indicator": "\u0627\u0644\u062E\u0644\u0637 \u0628\u064A\u0646 \u0627\u0644\u0646\u0648\u0639\u064A\u0646 \u0642\u062F \u064A\u064F\u0641\u0648\u0651\u062A \u0639\u0644\u0649 \u0627\u0644\u0634\u062E\u0635 \u062D\u0642\u0647 \u0641\u064A \u0627\u0644\u0645\u0637\u0627\u0644\u0628\u0629 \u0628\u0627\u0644\u0625\u0628\u0637\u0627\u0644 \u062E\u0644\u0627\u0644 \u0627\u0644\u0645\u062F\u0629 \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064A\u0629.",
