        "relevance": "\u0623\u0633\u0627\u0633 \u062F\u0633\u062A\u0648\u0631\u064A \u0645\u0647\u0645 \u0641\u064A \u062A\u0642\u064A\u064A\u0645 \u0628\u0646\u0648\u062F \u0639\u0642\u0648\u062F \u0627\u0644\u0625\u064A\u062C\u0627\u0631 \u0627\u0644\u0645\u062A\u0639\u0644\u0642\u0629 \u0628\u0627\u0644\u0625\u062E\u0644\u0627\u0621 \u0648\u0627\u0633\u062A\u0642\u0631\u0627\u0631 \u0627\u0644\u0633\u0643\u0646."
