        "source": "\u0642\u0627\u0646\u0648\u0646 \u0631\u0642\u0645 18 \u0644\u0633\u0646\u0629 2020 \u0648\u062A\u0639\u062F\u064A\u0644\u0627\u062A\u0647 \u0628\u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0631\u0642\u0645 158 \u0644\u0633\u0646\u0629 2022"
